from pathlib import Path
p=Path("DashboardV1.js")
s=p.read_text(encoding="utf-8-sig")
if "function getV115QuestCompletionState_" not in s:
    s += "\n\n" + "// V1.15 quest completion reporting\nfunction getV115QuestCompletionState_() {\n  const ss=SpreadsheetApp.openById(V1_TRACKER_ID);\n  const sh=ss.getSheetByName('Quest Dependency');\n  if(!sh) throw new Error('Quest Dependency sheet not found.');\n  const vals=sh.getDataRange().getDisplayValues();\n  const headers=vals[0].map(String);\n  const qCol=headers.findIndex(x=>/quest name/i.test(x));\n  const cCol=headers.findIndex(x=>/^completed$/i.test(x.trim()));\n  const qpCol=headers.findIndex(x=>/quest points|qp reward/i.test(x));\n  if(qCol<0||cCol<0) throw new Error('Quest Dependency needs Quest Name and Completed columns.');\n\n  const incomplete=[];\n  vals.slice(1).forEach((r,i)=>{\n    const quest=String(r[qCol]||'').trim();\n    if(!quest)return;\n    const done=/^(yes|true|complete|completed)$/i.test(String(r[cCol]||'').trim());\n    if(!done) incomplete.push({quest,qp:qpCol>=0?Number(r[qpCol]||0):0,row:i+2});\n  });\n  incomplete.sort((a,b)=>a.quest.localeCompare(b.quest));\n\n  const props=PropertiesService.getScriptProperties();\n  const current=Number((ss.getSheetByName('Your Stats').getRange('B34').getValue())||0);\n  let previous=Number(props.getProperty('V115_LAST_RECONCILED_QP')||current);\n  if(!props.getProperty('V115_LAST_RECONCILED_QP')) props.setProperty('V115_LAST_RECONCILED_QP',String(current));\n  const gain=Math.max(0,current-previous);\n\n  const dash=ss.getSheetByName('Dashboard');\n  const route=dash.getRange('A60:B69').getDisplayValues().map(r=>r[1]).filter(Boolean);\n  const next=dash.getRange('A73:B80').getDisplayValues();\n  const nextObj={}; next.forEach(r=>{if(r[0])nextObj[r[0]]=r[1]});\n  const nextQuest=nextObj['Quest']||nextObj['Next Quest']||'';\n\n  const likely=incomplete.map(q=>{\n    let score=0,reasons=[];\n    if(String(q.quest).toLowerCase()===String(nextQuest).toLowerCase()){score+=100;reasons.push('Next Session');}\n    const ri=route.findIndex(x=>String(x).toLowerCase()===q.quest.toLowerCase());\n    if(ri>=0){score+=50-ri;reasons.push('Current route');}\n    if(gain>0&&q.qp===gain){score+=80;reasons.push('Exact QP match');}\n    else if(gain>0&&q.qp>0&&q.qp<=gain){score+=20;reasons.push('Fits QP gain');}\n    return {...q,score,reasons};\n  }).filter(q=>q.score>0).sort((a,b)=>b.score-a.score||a.quest.localeCompare(b.quest));\n\n  return {currentQp:current,previousQp:previous,detectedGain:gain,incomplete,likely};\n}\n\nfunction getV115QuestCompletionState(){return getV115QuestCompletionState_();}\n\nfunction completeV115Quests(quests,source){\n  if(!Array.isArray(quests)||!quests.length)throw new Error('Select at least one quest.');\n  const ss=SpreadsheetApp.openById(V1_TRACKER_ID),sh=ss.getSheetByName('Quest Dependency');\n  const vals=sh.getDataRange().getDisplayValues(),headers=vals[0].map(String);\n  const qCol=headers.findIndex(x=>/quest name/i.test(x)),cCol=headers.findIndex(x=>/^completed$/i.test(x.trim()));\n  if(qCol<0||cCol<0)throw new Error('Quest Dependency columns not found.');\n  const wanted=new Set(quests.map(x=>String(x).toLowerCase()));\n  const changed=[];\n  vals.slice(1).forEach((r,i)=>{\n    if(wanted.has(String(r[qCol]||'').trim().toLowerCase())&&!/^(yes|true|complete|completed)$/i.test(String(r[cCol]||''))){\n      sh.getRange(i+2,cCol+1).setValue('Yes'); changed.push(String(r[qCol]).trim());\n    }\n  });\n  if(!changed.length)throw new Error('No incomplete quests matched the selection.');\n\n  let log=ss.getSheetByName('Quest Completion Log');\n  if(!log){log=ss.insertSheet('Quest Completion Log');log.appendRow(['Timestamp','Quest','Previous Status','New Status','Source','Transaction ID']);}\n  const tx=Utilities.getUuid(),now=new Date(),src=source||'Dashboard Manual';\n  changed.forEach(q=>log.appendRow([now,q,'No','Yes',src,tx]));\n  PropertiesService.getScriptProperties().setProperty('V115_LAST_RECONCILED_QP',\n    String(Number(ss.getSheetByName('Your Stats').getRange('B34').getValue())||0));\n  SpreadsheetApp.flush();\n  return {ok:true,changed,transactionId:tx,state:getV115QuestCompletionState_()};\n}\n\nfunction undoV115QuestCompletion(transactionId){\n  const ss=SpreadsheetApp.openById(V1_TRACKER_ID),log=ss.getSheetByName('Quest Completion Log');\n  if(!log)throw new Error('No quest completion log exists.');\n  const lv=log.getDataRange().getDisplayValues(),quests=lv.slice(1).filter(r=>r[5]===transactionId).map(r=>r[1]);\n  if(!quests.length)throw new Error('Transaction not found.');\n  const sh=ss.getSheetByName('Quest Dependency'),vals=sh.getDataRange().getDisplayValues(),headers=vals[0].map(String);\n  const qCol=headers.findIndex(x=>/quest name/i.test(x)),cCol=headers.findIndex(x=>/^completed$/i.test(x.trim()));\n  const set=new Set(quests.map(x=>x.toLowerCase()));\n  vals.slice(1).forEach((r,i)=>{if(set.has(String(r[qCol]).toLowerCase()))sh.getRange(i+2,cCol+1).setValue('No')});\n  const tx=Utilities.getUuid(),now=new Date();\n  quests.forEach(q=>log.appendRow([now,q,'Yes','No','Dashboard Undo',tx]));\n  SpreadsheetApp.flush();\n  return {ok:true,changed:quests,state:getV115QuestCompletionState_()};\n}\n"
p.write_text(s,encoding="utf-8",newline="\n")

p=Path("V1.html")
h=p.read_text(encoding="utf-8-sig")
h=h.replace("V1.14.4","V1.15")
if 'id="v115Modal"' not in h:
    pos=h.lower().rfind("</body>")
    if pos<0: raise SystemExit("Could not find </body> in V1.html")
    h=h[:pos]+'<style id="v115styles">\n.v115Report{background:#f0b83d;color:#321b0c;border:0;border-radius:9px;padding:9px 12px;font-weight:900;cursor:pointer}\n.v115Banner{position:fixed;z-index:9998;top:-220px;left:50%;transform:translateX(-50%);width:min(720px,calc(100% - 30px));background:#fff7df;color:#25180e;border:3px solid #d99b29;border-radius:0 0 14px 14px;box-shadow:0 12px 35px rgba(0,0,0,.38);padding:14px 16px;transition:top .45s ease}\n.v115Banner.show{top:0}.v115Banner b{font-size:15px}.v115BannerActions{margin-top:9px;display:flex;gap:8px}\n.v115Modal{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.68);display:none;align-items:center;justify-content:center;padding:20px}\n.v115Modal.show{display:flex}.v115Box{width:min(760px,100%);max-height:88vh;overflow:auto;background:#f5efe4;color:#25180e;border:2px solid #8c5b2b;border-radius:14px;box-shadow:0 18px 50px rgba(0,0,0,.45)}\n.v115Head{position:sticky;top:0;background:#321b0c;color:#ffe2a1;padding:13px 15px;display:flex;justify-content:space-between;z-index:2}\n.v115Body{padding:14px}.v115Search{width:100%;padding:10px;border:1px solid #b79b74;border-radius:8px;margin:8px 0 12px}\n.v115Quest{display:grid;grid-template-columns:24px 1fr auto;gap:8px;padding:8px;border-bottom:1px solid #ded1bb;align-items:center}\n.v115Quest small{display:block;color:#756452;margin-top:2px}.v115Section{font-size:11px;font-weight:900;text-transform:uppercase;color:#6d4b24;margin:12px 0 5px}\n.v115All summary{cursor:pointer;font-weight:900;padding:10px 0}.v115Foot{position:sticky;bottom:0;background:#eee1ca;border-top:1px solid #c9b28d;padding:11px 14px;display:flex;justify-content:space-between;gap:10px;align-items:center}\n.v115Btn{border:1px solid #8c5b2b;background:#fffaf1;color:#321b0c;border-radius:8px;padding:8px 11px;font-weight:900;cursor:pointer}.v115Btn.primary{background:#5a3217;color:#fff3d4}\n</style>\n<div id="v115Banner" class="v115Banner"><b>Quest Points increased</b><div id="v115BannerText"></div><div class="v115BannerActions"><button class="v115Btn primary" onclick="openV115QuestModal(\'QP Reconciliation\')">Review completed quests</button><button class="v115Btn" onclick="hideV115Banner()">Dismiss</button></div></div>\n<div id="v115Modal" class="v115Modal"><div class="v115Box"><div class="v115Head"><b>Report Completed Quest</b><button class="v115Btn" onclick="closeV115QuestModal()">Close</button></div><div class="v115Body"><div id="v115Qp"></div><input id="v115Search" class="v115Search" placeholder="Search incomplete quests..." oninput="renderV115Quests()"><div class="v115Section">Likely completed</div><div id="v115Likely"></div><details class="v115All" open><summary>All incomplete quests (A-Z)</summary><div id="v115All"></div></details></div><div class="v115Foot"><span id="v115Selected">Selected: 0 quests</span><button class="v115Btn primary" onclick="confirmV115Quests()">Confirm completions</button></div></div></div>\n<script>\nlet v115State=null,v115Selected=new Set(),v115Source=\'Dashboard Manual\',v115LastTx=\'\';\nfunction loadV115(){\n google.script.run.withSuccessHandler(s=>{v115State=s;if(s.detectedGain>0){document.getElementById(\'v115BannerText\').textContent=`Detected +${s.detectedGain} QP (${s.previousQp} to ${s.currentQp}).`;setTimeout(()=>document.getElementById(\'v115Banner\').classList.add(\'show\'),250)}}).getV115QuestCompletionState();\n}\nfunction hideV115Banner(){document.getElementById(\'v115Banner\').classList.remove(\'show\')}\nfunction openV115QuestModal(src){v115Source=src||\'Dashboard Manual\';v115Selected.clear();document.getElementById(\'v115Modal\').classList.add(\'show\');google.script.run.withSuccessHandler(s=>{v115State=s;renderV115Quests()}).getV115QuestCompletionState()}\nfunction closeV115QuestModal(){document.getElementById(\'v115Modal\').classList.remove(\'show\')}\nfunction v115Row(q){const checked=v115Selected.has(q.quest);return `<label class="v115Quest"><input type="checkbox" ${checked?\'checked\':\'\'} onchange="toggleV115(\'${String(q.quest).replace(/\'/g,"\\\\\'")}\',this.checked)"><span><b>${q.quest}</b>${q.reasons&&q.reasons.length?`<small>${q.reasons.join(\' - \')}</small>`:\'\'}</span><span>${q.qp||0} QP</span></label>`}\nfunction renderV115Quests(){if(!v115State)return;const f=(document.getElementById(\'v115Search\').value||\'\').toLowerCase();document.getElementById(\'v115Qp\').textContent=v115State.detectedGain?`Detected QP gain: +${v115State.detectedGain}`:\'No unresolved QP increase.\';document.getElementById(\'v115Likely\').innerHTML=(v115State.likely||[]).filter(q=>q.quest.toLowerCase().includes(f)).map(v115Row).join(\'\')||\'<small>No likely matches.</small>\';document.getElementById(\'v115All\').innerHTML=(v115State.incomplete||[]).filter(q=>q.quest.toLowerCase().includes(f)).map(v115Row).join(\'\');updateV115Selected()}\nfunction toggleV115(q,on){on?v115Selected.add(q):v115Selected.delete(q);renderV115Quests()}\nfunction updateV115Selected(){if(!v115State)return;const rows=v115State.incomplete.filter(q=>v115Selected.has(q.quest));const qp=rows.reduce((a,b)=>a+(Number(b.qp)||0),0);let t=`Selected: ${rows.length} quest${rows.length===1?\'\':\'s\'} - ${qp} QP`;if(v115State.detectedGain)t+=qp===v115State.detectedGain?\' - Matches detected change\':` - Detected +${v115State.detectedGain}`;document.getElementById(\'v115Selected\').textContent=t}\nfunction confirmV115Quests(){if(!v115Selected.size)return alert(\'Select at least one quest.\');const names=[...v115Selected];if(!confirm(`Mark these quests complete?\\n\\n${names.join(\'\\n\')}`))return;google.script.run.withFailureHandler(e=>alert(\'Quest update failed: \'+e.message)).withSuccessHandler(r=>{v115LastTx=r.transactionId;v115State=r.state;closeV115QuestModal();hideV115Banner();alert(`${r.changed.length} quest${r.changed.length===1?\'\':\'s\'} marked complete.`);location.reload()}).completeV115Quests(names,v115Source)}\ndocument.addEventListener(\'DOMContentLoaded\',()=>{const controls=document.querySelector(\'.controls\');if(controls&&!document.getElementById(\'v115Report\')){const b=document.createElement(\'button\');b.id=\'v115Report\';b.className=\'v115Report\';b.textContent=\'Report Completed Quest\';b.onclick=()=>openV115QuestModal(\'Dashboard Manual\');controls.appendChild(b)}loadV115()});\n</script>\n'+"\n"+h[pos:]
p.write_text(h,encoding="utf-8",newline="\n")
print("V1.15 Quest Completion Center installed.")
